local OverseaClubBossDetailsDialog = Class("OverseaClubBossDetailsDialog")

function OverseaClubBossDetailsDialog:__init()
    self._curBossPlanVo = nil        --当前bossVo
    self._followMonsts = nil         --小怪
end

function OverseaClubBossDetailsDialog:__delete()
    self._curBossPlanVo = nil
    self._followMonsts = nil         --小怪
end

function OverseaClubBossDetailsDialog:Awake()
    self.parameters = self.controller.Argument.parameters
    if not isNull(self.parameters.questId) then
        self.questId = self.parameters.questId
    end
    if isNull(self.questId) then return end

    local bossId = self:GetBossId(self.questId)
    if isNull(bossId) then return end

    self._curBossPlanVo = CardConfMgr:GetInstance():GetBaseMonstVo(bossId)

    if not self._curBossPlanVo then
        return
    end
    --关卡阵容信息
    local lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.questId)
    if lineUpInfo then
        lineUpInfo = checkTable(lineUpInfo)
        --只有一波怪
        lineUpInfo = checkTable(lineUpInfo[1])
        self:FillMonstInfo(lineUpInfo.wave1NpcId)
    end

    self:InitBossDrawNode()
    self:RefreshMonsterImage(self._curBossPlanVo)

    local vo = ClubUtils.GetBossPassVo(self.questId)
    if next(vo) then
        CfUtils.FillText(self.TxtContent,string.gsub(vo.illustrate,"\\n", "\n"))
    end
end

function OverseaClubBossDetailsDialog:InitBossDrawNode()
    ---@type UnityEngine.RectTransform
    self.BossDrawingNodeRT = KTool.GetComponent(self.BossDrawingNode.gameObject, typeof(CS.UnityEngine.RectTransform))
    CfUtils.SetActive(self.BossDrawingNode.gameObject,false)
end

---RefreshMonsterImage
---刷新怪物立绘
---@param monsterTypeVo MonsterTypeVo 皮肤id
function OverseaClubBossDetailsDialog:RefreshMonsterImage(monsterTypeVo)
    self.BossDrawingNode:Execute(checkNumber(monsterTypeVo.skinId))
end

function OverseaClubBossDetailsDialog:GetBossId()
    local data = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.questId)
    for i, v in pairs(data) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
               return v.wave1NpcId[k]
            end
        end
    end
    return nil
end


